To implement a queue using two stacks in Python, we can use one stack for enqueuing (adding elements) and another for dequeuing (removing elements). Here’s how you can do it:

```python
class QueueUsingStacks:
    def __init__(self):
        # Two stacks to simulate the queue
        self.stack_enqueue = []
        self.stack_dequeue = []

    def enqueue(self, value):
        # Add the value to the stack used for enqueuing
        self.stack_enqueue.append(value)

    def dequeue(self):
        # Transfer all elements from stack_enqueue to stack_dequeue if stack_dequeue is empty
        if not self.stack_dequeue:
            while self.stack_enqueue:
                self.stack_dequeue.append(self.stack_enqueue.pop())
        # Pop from stack_dequeue if it has elements, otherwise raise an error
        if not self.stack_dequeue:
            raise IndexError("dequeue from an empty queue")
        return self.stack_dequeue.pop()

    def is_empty(self):
        # Check if both stacks are empty
        return not self.stack_enqueue and not self.stack_dequeue

# Example usage:
q = QueueUsingStacks()
q.enqueue(1)
q.enqueue(2)
print(q.dequeue())  # Output

